def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    DIV0 = "#DIV/0!"
    CYCLE = "#CYCLE!"

    def is_error(x):
        return isinstance(x, str)

    def cell_key(name):
        return ord(name[0]) - 65, int(name[1:])

    class Parser:
        def __init__(self, text):
            self.s = text
            self.i = 0

        def skip(self):
            while self.i < len(self.s) and self.s[self.i].isspace():
                self.i += 1

        def eat(self, token):
            self.skip()
            if self.s.startswith(token, self.i):
                self.i += len(token)
                return True
            return False

        def parse(self):
            return self.expr()

        def expr(self):
            node = self.term()
            while True:
                self.skip()
                if self.eat("+"):
                    node = ("bin", "+", node, self.term())
                elif self.eat("-"):
                    node = ("bin", "-", node, self.term())
                else:
                    return node

        def term(self):
            node = self.unary()
            while True:
                self.skip()
                if self.eat("*"):
                    node = ("bin", "*", node, self.unary())
                elif self.eat("/"):
                    node = ("bin", "/", node, self.unary())
                else:
                    return node

        def unary(self):
            self.skip()
            if self.eat("-"):
                return ("neg", self.unary())
            return self.atom()

        def word(self):
            self.skip()
            start = self.i
            while self.i < len(self.s) and self.s[self.i].isalnum():
                self.i += 1
            return self.s[start:self.i]

        def atom(self):
            self.skip()
            if self.eat("("):
                node = self.expr()
                self.eat(")")
                return node

            token = self.word()
            if token.isdigit():
                return ("num", int(token))

            self.skip()
            if self.eat("("):
                if token == "IF":
                    left = self.expr()
                    self.skip()
                    for op in ("<>", "<=", ">=", "=", "<", ">"):
                        if self.s.startswith(op, self.i):
                            self.i += len(op)
                            break
                    self.eat(",")
                    yes = self.expr()
                    self.eat(",")
                    no = self.expr()
                    self.eat(")")
                    return ("if", op, left, yes, no)

                args = []
                while True:
                    self.skip()
                    start = self.i
                    possible = self.word()
                    self.skip()
                    if possible and self.eat(":"):
                        end = self.word()
                        args.append(("range", possible, end))
                    else:
                        self.i = start
                        args.append(("formula", self.expr()))
                    if self.eat(")"):
                        break
                    self.eat(",")
                return ("func", token, args)

            return ("ref", token)

    trees = {}
    for name, content in cells.items():
        trees[name] = ("num", int(content)) if not content.startswith("=") else Parser(content[1:]).parse()

    state = {}
    values = {}

    def evaluate_cell(name):
        if name not in cells:
            return 0
        if state.get(name) == 2:
            return values[name]
        if state.get(name) == 1:
            return CYCLE

        state[name] = 1
        value = evaluate(trees[name])
        state[name] = 2
        values[name] = value
        return value

    def trunc_div(a, b):
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    def evaluate(node):
        kind = node[0]

        if kind == "num":
            return node[1]

        if kind == "ref":
            return evaluate_cell(node[1])

        if kind == "neg":
            value = evaluate(node[1])
            return value if is_error(value) else -value

        if kind == "bin":
            left = evaluate(node[2])
            if is_error(left):
                return left
            right = evaluate(node[3])
            if is_error(right):
                return right

            op = node[1]
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return DIV0
            return trunc_div(left, right)

        if kind == "if":
            left = evaluate(node[2])
            if is_error(left):
                return left
            right = evaluate(node[3])
            if is_error(right):
                return right

            op = node[1]
            ok = {
                "=": left == right,
                "<>": left != right,
                "<": left < right,
                "<=": left <= right,
                ">": left > right,
                ">=": left >= right,
            }[op]
            return evaluate(node[4] if ok else node[5])

        values_list = []
        for arg in node[2]:
            if arg[0] == "formula":
                value = evaluate(arg[1])
                if is_error(value):
                    return value
                values_list.append(value)
            else:
                c1, r1 = cell_key(arg[1])
                c2, r2 = cell_key(arg[2])
                for row in range(min(r1, r2), max(r1, r2) + 1):
                    for col in range(min(c1, c2), max(c1, c2) + 1):
                        name = chr(65 + col) + str(row)
                        if name in cells:
                            value = evaluate_cell(name)
                            if is_error(value):
                                return value
                            values_list.append(value)

        if node[1] == "SUM":
            return sum(values_list)
        if not values_list:
            return 0
        return min(values_list) if node[1] == "MIN" else max(values_list)

    return {name: evaluate_cell(name) for name in cells}
